  ('02c0ffb3-3c10-44c1-85c1-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'gerc', 'regulation_versions', '[{"from":"2016-01-01","label":"GERC Net Metering Rooftop Solar PV Grid Interactive Systems Regulations 2016, as amended before the Fifth Amendment (effective date approximate)"},{"from":"2025-11-04","label":"GERC Net Metering Rooftop Solar PV Grid Interactive Systems Regulations 2016 — Fifth Amendment (effective 4-Nov-2025, as reported)"}]'::jsonb, '2020-01-01', null, 'Research report 26-Oct-2026 / GERC Net Metering Rooftop Regulations 2016 as amended (trade-press summary)', 'India solar distributor CRM blueprint.md §3.3 [S37][S38][S39]', 'low', 'unverified', true, 'info', false, 'Used only to LABEL which regulation version applies from the commissioning date. Dates and labels come from trade-press summaries; the Surya Roshni v. PGVCL dispute on which version governs banking charges is unresolved (V-10, V-26). Verify against primary source before relying', null),
  ('ec58813a-eb58-4ea5-8e95-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'sla', 'lead_acceptance_reassign_minutes.hot', '15'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'Minutes after the DSM alert before an unaccepted HOT lead is auto-reassigned (Reminder 1 → DSM alert → auto-reassignment).', null),
  ('9f16f34c-a216-4a11-89c1-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'sla', 'lead_acceptance_reassign_minutes.warm', '60'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'Minutes after the DSM alert before an unaccepted WARM lead is auto-reassigned.', null),
  ('30fda401-2dfd-42ef-833f-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'sla', 'lead_acceptance_reassign_minutes.cold', '120'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'Minutes after the DSM alert before an unaccepted COLD lead is auto-reassigned.', null),
  ('9d628382-9c62-49b6-89a6-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'routing', 'score_weights', '{"score":0.6,"load":0.2,"band_fit":0.2}'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'Weights used to rank eligible distributors: distributor score (0–100 scaled to 0–1), spare capacity (fewer open leads is better) and how centrally the lead size sits in the distributor’s MW band. The three weights are normalised before use.', null),
  ('70f80392-6ff8-46ef-86df-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'routing', 'load_reference_leads', '20'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'Number of open leads at which a distributor’s load factor drops to zero in the ranking above.', null),
  ('ddc70412-dcc7-4dbc-8dac-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'routing', 'max_auto_reassignments', '3'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'After this many automatic assignments (first assignment included) a lead that is rejected or not accepted in time goes to the DSM as unassigned instead of being routed again.', null),
  ('ca4238cd-c742-4c84-8c54-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'lead', 'dedupe_similarity_threshold', '0.6'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'Bigram-Jaccard similarity (0–1) at or above which two names in the same pincode are treated as a possible duplicate — the same intent as pg_trgm similarity in the database function.', null),
  ('11569607-1256-4135-8c56-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'lead', 'qualification_required_fields', '["requirement_text","timeline_bucket","decision_maker","capacity_kw"]'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'Lead fields that must be known (timeline and decision maker not “unknown”) before a lead moves to Qualified. Allowed keys: requirement_text, timeline_bucket, decision_maker, capacity_kw, budget_inr, segment.', null),
  ('bfb5a7a6-beb5-4bdb-8c4b-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'followup', 'email_reminders', 'true'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'When true, follow-up reminders and acceptance reminders are also e-mailed to the lead owner (and the DSM on breach), in addition to the in-app notification. Staff e-mails need no customer consent.', null),
  ('6efe3086-6dfe-46cf-873f-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'followup', 'retry_minutes', '240'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'Working minutes after which a retry is scheduled when a call is not answered or the customer asks to be called back later.', null),
  ('f390f222-f290-4f19-8f09-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'followup', 'max_days_ahead', '180'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/leads.md (leads module defaults)', 'high', 'verified', true, 'info', false, 'The furthest ahead a next follow-up date may be set (guards against typing the wrong year).', null),
  ('1a4302eb-1b43-41c4-81d4-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'opportunity', 'indicative_rate_per_kw', '50000'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'Management estimate for pipeline sizing only — not a quotation price', 'low', 'unverified', true, 'info', false, 'INDICATIVE rupees per kW used to estimate expected_value when a lead becomes an opportunity (kW × rate). Always labelled "indicative" in the UI; replaced by the real quote total once a quotation exists. Edit to match current market pricing.', null),
  ('fe826088-1826-4826-8382-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'opportunity', 'default_probability', '{"hot":60,"warm":40,"cold":20}'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'Sales management starting point', 'low', 'unverified', true, 'info', false, 'Starting win probability (%) by lead temperature when a lead is converted. The salesperson overrides it in step 20.', null),
  ('e84ab520-eb4a-4ea4-8ed4-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'pmsg', 'special_category_states', '["Arunachal Pradesh","Assam","Manipur","Meghalaya","Mizoram","Nagaland","Sikkim","Tripura","Himachal Pradesh","Uttarakhand","Jammu and Kashmir","Ladakh","Andaman and Nicobar Islands","Lakshadweep"]'::jsonb, '2020-01-01', null, 'MNRE PM Surya Ghar guidelines — special category states (reading not confirmed)', 'Verify against the current MNRE programme guideline before activating', 'low', 'unverified', false, 'info', false, 'States treated as "special category" for the higher residential CFA. INACTIVE until a compliance officer verifies the list: while inactive the site form only shows a hint and the flag must be set by hand (special_category_state override on the site). Verify against primary source before relying.', null),
  ('79eb44d0-7ceb-47be-87ee-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'survey', 'max_photos', '10'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'Storage and review workload', 'high', 'verified', true, 'info', false, 'Maximum number of photos kept on one site survey.', null),
  ('10f544b0-13f5-412f-815f-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'survey', 'reminder_hours_before', '[24,2]'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'Field operations', 'high', 'verified', true, 'info', false, 'Hours before a scheduled site visit at which the surveyor is reminded (one notification per entry).', null),
