  ('43424b22-4242-4414-8404-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'site', 'name_match_min_score', '0.85'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'Data-quality policy for gate G12', 'medium', 'verified', true, 'info', false, 'Minimum similarity (0–1) between the name on the DISCOM bill and the applicant name to count as a match. Lower values are more forgiving; a mismatch only raises a G12 warning.', null),
  ('895a489a-885a-4875-8865-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'quote', 'default_validity_days', '7'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'prompt.md §9 Stage 4 (default quote validity)', 'high', 'verified', true, 'warning', false, 'Default quote validity in calendar days. The actual default is capped at the price horizon and, when relying on the exemption, the exemption date.', null),
