  ('798ef076-788e-4778-87e8-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'quote', 'discount_bands', '[{"min_pct":0,"max_pct":2,"role_chain":[]},{"min_pct":2,"max_pct":5,"role_chain":["dsm"]},{"min_pct":5,"max_pct":8,"role_chain":["dsm","regional_head"]},{"min_pct":8,"max_pct":null,"role_chain":["dsm","regional_head","management"]}]'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'prompt.md §9 Stage 4 (approval matrix DSM → Regional Head → Management)', 'hypothesis', 'unverified', true, 'warning', false, 'Fallback commercial-lane discount bands, used only when approval_rules has no active commercial rows. Placeholder thresholds — Management to confirm. Sequential steps within a band.', null),
