  ('d93cddf6-d83c-4d73-8de3-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'order', 'pi_validity_days', '15'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/orders.md — operational defaults for PI, credit and sales orders', 'high', 'verified', true, 'warning', false, 'Days a proforma invoice stays valid after issue (valid_till = issue date + this many days).', null),
