  ('8cd20733-8dd2-48ed-88fd-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'order', 'management_approval_above', '2500000'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/orders.md — operational defaults for PI, credit and sales orders', 'medium', 'verified', true, 'info', false, 'PIs and sales orders whose total is at or above this amount (INR) need a second approval step by Management after Accounts.', null),
  ('79456cb3-7a45-47b4-87c4-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'gujarat', 'pmsg_no_connectivity_agreement', 'true'::jsonb, '2025-11-04', null, 'GERC Net Metering Rooftop Regulations — Fifth Amendment (as reported)', 'India solar distributor CRM blueprint.md §3.3 (S37, S38)', 'medium', 'unverified', false, 'info', false, 'Gujarat PMSG rooftop systems commissioned on/after the Fifth Amendment need no separate written connectivity agreement; the agreement begins on the commissioning date. While this rule is inactive the installation flag "no_connectivity_agreement" is a manual entry only. Verify against primary source before relying.', null),
