  ('57ded723-58de-459d-85ad-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'subsidy', 'legacy_reminder_days', '[14,7,3]'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'docs/api/postsale-channel.md — operating defaults for the post-sale and channel modules', 'high', 'verified', true, 'info', false, 'Operating default — days before the legacy CFA claim deadline at which reminders escalate: first value to the DSM, next to the Sales Manager, last to Management.', null),
