  ('a1983849-9e98-49f9-8a49-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-09-28T06:30:00.000Z', null, 'reporting', 'calendar_lookahead_days', '60'::jsonb, '2020-01-01', null, 'Future Solar operating default', 'Reporting module default — change under Admin → Rule Config', 'high', 'verified', true, 'info', false, 'Operating default — compliance-calendar items due within this many days appear on the Today queue.', null)
insert into public.message_templates (id, org_id, created_at, updated_at, created_by, key, channel, category, purpose, language, subject, body, dlt_template_id, dlt_header, whatsapp_template_name, version, active) values
  ('5f96355b-6096-4619-8629-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'consent_notice', 'in_app', 'service', 'service', 'en', 'Consent notice v1', 'Future Solar Pvt. Ltd. ({{company}}) will use your name, mobile number, e-mail and site details only to respond to your solar enquiry. By ticking the boxes below you allow us to contact you by {{channels}} for: {{purposes}}. Your details will be shared only with: {{recipients}}. You can withdraw your consent at any time — reply STOP on WhatsApp or SMS, tell us on a call, or use the link in any message. After you withdraw, we will not send you promotional messages for 90 days. Notice version: {{notice_version}}.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000002', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'consent_notice', 'in_app', 'service', 'service', 'hi', 'Consent notice v1', 'फ्यूचर सोलर प्राइवेट लिमिटेड ({{company}}) आपकी सोलर पूछताछ का उत्तर देने के लिए ही आपके नाम, मोबाइल नंबर, ई-मेल और साइट के विवरण का उपयोग करेगी। नीचे दिए गए बॉक्स पर टिक करके आप हमें {{channels}} के माध्यम से इन उद्देश्यों के लिए संपर्क करने की अनुमति देते हैं: {{purposes}}। आपका विवरण केवल इनके साथ साझा किया जाएगा: {{recipients}}। आप किसी भी समय अपनी सहमति वापस ले सकते हैं — WhatsApp या SMS पर STOP लिखें, कॉल पर हमें बताएँ, या किसी भी संदेश में दिए गए लिंक का उपयोग करें। सहमति वापस लेने के बाद हम 90 दिनों तक आपको प्रचार संदेश नहीं भेजेंगे। सूचना संस्करण: {{notice_version}}।', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000003', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'consent_notice', 'in_app', 'service', 'service', 'gu', 'Consent notice v1', 'ફ્યુચર સોલર પ્રાઇવેટ લિમિટેડ ({{company}}) તમારી સોલર પૂછપરછનો જવાબ આપવા માટે જ તમારું નામ, મોબાઇલ નંબર, ઈ-મેઇલ અને સાઇટની વિગતોનો ઉપયોગ કરશે. નીચેના બૉક્સ પર ટિક કરીને તમે અમને {{channels}} દ્વારા આ હેતુઓ માટે સંપર્ક કરવાની પરવાનગી આપો છો: {{purposes}}. તમારી વિગતો ફક્ત આમની સાથે શેર કરવામાં આવશે: {{recipients}}. તમે કોઈપણ સમયે તમારી સંમતિ પાછી ખેંચી શકો છો — WhatsApp અથવા SMS પર STOP લખો, કૉલ પર અમને જણાવો, અથવા કોઈપણ સંદેશમાંની લિંકનો ઉપયોગ કરો. સંમતિ પાછી ખેંચ્યા પછી અમે 90 દિવસ સુધી તમને પ્રમોશનલ સંદેશા મોકલીશું નહીં. નોટિસ સંસ્કરણ: {{notice_version}}.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000004', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.acknowledgement', 'whatsapp', 'utility', 'transactional', 'en', null, 'Namaste {{1}}, thank you for your solar enquiry with Future Solar. Your reference is {{2}}. {{3}} will contact you shortly. Reply STOP to opt out.', null, null, 'fs_acknowledgement_v1_en', 1, true),
  ('5f96355b-6096-4619-8629-000000000005', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.acknowledgement', 'whatsapp', 'utility', 'transactional', 'hi', null, 'नमस्ते {{1}}, फ्यूचर सोलर में सोलर पूछताछ के लिए धन्यवाद। आपका संदर्भ क्रमांक {{2}} है। {{3}} जल्द ही आपसे संपर्क करेंगे। बंद करने के लिए STOP लिखें।', null, null, 'fs_acknowledgement_v1_hi', 1, true),
  ('5f96355b-6096-4619-8629-000000000006', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.acknowledgement', 'whatsapp', 'utility', 'transactional', 'gu', null, 'નમસ્તે {{1}}, ફ્યુચર સોલરમાં સોલર પૂછપરછ બદલ આભાર. તમારો સંદર્ભ ક્રમાંક {{2}} છે. {{3}} ટૂંક સમયમાં તમારો સંપર્ક કરશે. બંધ કરવા માટે STOP લખો.', null, null, 'fs_acknowledgement_v1_gu', 1, true),
  ('5f96355b-6096-4619-8629-000000000007', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.followup_reminder', 'whatsapp', 'utility', 'service', 'en', null, 'Namaste {{1}}, this is a reminder from Future Solar about your solar enquiry {{2}}. {{3}} will call you on {{4}}. Reply STOP to opt out.', null, null, 'fs_followup_reminder_v1_en', 1, true),
  ('5f96355b-6096-4619-8629-000000000008', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.quote_sent', 'whatsapp', 'utility', 'transactional', 'en', null, 'Namaste {{1}}, your Future Solar quotation {{2}} for {{3}} kW is ready and valid until {{4}}. {{5}} will walk you through it. Reply STOP to opt out.', null, null, 'fs_quote_sent_v1_en', 1, true),
  ('5f96355b-6096-4619-8629-000000000009', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.payment_reminder', 'whatsapp', 'utility', 'transactional', 'en', null, 'Namaste {{1}}, a payment of ₹ {{2}} against proforma invoice {{3}} is due. Your order will be processed once it is received. Reply STOP to opt out.', null, null, 'fs_payment_reminder_v1_en', 1, true),
  ('5f96355b-6096-4619-8629-00000000000a', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.optout_confirmation', 'whatsapp', 'service', 'service', 'en', null, 'You have been opted out of messages from Future Solar. We will not send you promotional messages for 90 days. Service messages about an existing order may still be sent.', null, null, 'fs_optout_confirmation_v1_en', 1, true),
  ('5f96355b-6096-4619-8629-00000000000b', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.optout_confirmation', 'whatsapp', 'service', 'service', 'hi', null, 'आपको फ्यूचर सोलर के संदेशों से हटा दिया गया है। हम 90 दिनों तक आपको प्रचार संदेश नहीं भेजेंगे। किसी मौजूदा ऑर्डर से जुड़े सेवा संदेश फिर भी भेजे जा सकते हैं।', null, null, 'fs_optout_confirmation_v1_hi', 1, true),
  ('5f96355b-6096-4619-8629-00000000000c', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'wa.optout_confirmation', 'whatsapp', 'service', 'service', 'gu', null, 'તમને ફ્યુચર સોલરના સંદેશાઓમાંથી દૂર કરવામાં આવ્યા છે. અમે 90 દિવસ સુધી તમને પ્રમોશનલ સંદેશા મોકલીશું નહીં. હાલના ઓર્ડર અંગેના સેવા સંદેશા હજી પણ મોકલવામાં આવી શકે છે.', null, null, 'fs_optout_confirmation_v1_gu', 1, true),
  ('5f96355b-6096-4619-8629-00000000000d', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'sms.acknowledgement', 'sms', 'utility', 'transactional', 'en', null, 'Dear {#var#}, thank you for your solar enquiry with Future Solar. Ref {#var#}. {#var#} will call you shortly. Reply STOP to opt out.', 'TO-BE-REGISTERED', 'FUTSLR', null, 1, true),
  ('5f96355b-6096-4619-8629-00000000000e', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'sms.followup_reminder', 'sms', 'utility', 'service', 'en', null, 'Dear {#var#}, Future Solar will call you on {#var#} about your enquiry {#var#}. Reply STOP to opt out.', 'TO-BE-REGISTERED', 'FUTSLR', null, 1, true),
  ('5f96355b-6096-4619-8629-00000000000f', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'sms.quote_sent', 'sms', 'utility', 'transactional', 'en', null, 'Dear {#var#}, your Future Solar quotation {#var#} is ready and valid until {#var#}. Reply STOP to opt out.', 'TO-BE-REGISTERED', 'FUTSLR', null, 1, true),
  ('5f96355b-6096-4619-8629-000000000010', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'sms.payment_reminder', 'sms', 'utility', 'transactional', 'en', null, 'Dear {#var#}, Rs {#var#} against proforma invoice {#var#} is due. Please pay to proceed with your order. Reply STOP to opt out.', 'TO-BE-REGISTERED', 'FUTSLR', null, 1, true),
  ('5f96355b-6096-4619-8629-000000000011', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'sms.optout_confirmation', 'sms', 'service', 'service', 'en', null, 'You are opted out of Future Solar promotional messages for 90 days. Service messages about existing orders may continue.', 'TO-BE-REGISTERED', 'FUTSLR', null, 1, true),
  ('5f96355b-6096-4619-8629-000000000012', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'sms.promo_subsidy_deadline', 'sms', 'marketing', 'promotional', 'en', null, 'Dear {#var#}, subsidy claim and ALMM deadlines are near. Talk to Future Solar about your rooftop solar plan: {#var#}. Reply STOP to opt out.', 'TO-BE-REGISTERED', 'FUTSLR', null, 1, true),
  ('5f96355b-6096-4619-8629-000000000013', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'clause.duty_change', 'email', 'service', 'service', 'en', 'Change in customs duty', 'Prices are based on the customs duty rates in force on {{price_date}}. If basic customs duty, AIDC, anti-dumping duty or any other levy on modules, cells or inverters changes before dispatch, the price will be revised by the amount of the change and a revised quotation will be issued.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000014', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'clause.gst_change', 'email', 'service', 'service', 'en', 'Change in GST', 'Prices are exclusive of GST. GST is charged at the rate in force at the time of supply, not on the order date. If the rate or the HSN classification changes before supply, the invoice will carry the rate then applicable.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000015', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'clause.almm_change', 'email', 'service', 'service', 'en', 'Change in ALMM listing', 'Supply is of models listed on the ALMM on the date of this quotation. If a listed model or cell source is removed, suspended or becomes ineligible for this project before commissioning, Future Solar may substitute an eligible model of equal or higher rating, or revise this quotation, with your written approval.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000016', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'clause.price_validity', 'email', 'service', 'service', 'en', 'Price validity', 'This quotation is valid until {{validity_date}}. It lapses earlier if a duty, GST rate, ALMM listing or exemption date that it depends on changes; a revised quotation will then be issued.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000017', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'clause.payment_terms_default', 'email', 'service', 'service', 'en', 'Payment terms', '{{advance_pct}} % advance with the purchase order; the balance against dispatch documents before delivery. Subsidy (CFA) is credited by the Government to the customer''s bank account and is not part of the amount payable to Future Solar.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000018', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'internal.lead_acceptance_due', 'in_app', 'service', 'service', 'en', 'Lead awaiting acceptance', 'Lead {{lead_name}} ({{segment}}, {{temperature}}) must be accepted by {{due_at}}. Accept or reject it to stop the clock.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-000000000019', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'internal.followup_overdue', 'in_app', 'service', 'service', 'en', 'Follow-up overdue', 'The follow-up with {{lead_name}} was due {{due_at}}. Log the contact and set the next follow-up date.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-00000000001a', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'internal.quote_followup', 'in_app', 'service', 'service', 'en', 'Quote follow-up due', 'Quotation {{quote_no}} was sent {{days}} days ago. Follow up with the customer; escalation follows day 7.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-00000000001b', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'internal.approval_pending', 'in_app', 'service', 'service', 'en', 'Approval waiting', '{{entity}} {{ref}} is waiting for your decision in the {{lane}} lane. SLA: {{due_at}}.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-00000000001c', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'internal.legacy_claim_countdown', 'in_app', 'service', 'service', 'en', 'Legacy CFA claim deadline', '{{count}} legacy-cohort subsidy claim(s) must be received by {{deadline}} — {{days}} day(s) left. Open the daily work-list.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-00000000001d', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'internal.bg_expiry', 'in_app', 'service', 'service', 'en', 'Bank guarantee expiring', 'The bank guarantee of {{dealer}} expires on {{date}} ({{days}} days). Ask for a renewal before the vendor registration lapses.', null, null, null, 1, true),
  ('5f96355b-6096-4619-8629-00000000001e', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, 'internal.sop_deadline', 'in_app', 'service', 'service', 'en', 'MNRE SOP deadline', 'Complaint {{complaint_ref}} against {{dealer}} is at the {{stage}} stage; the next step is due {{due_at}}.', null, null, null, 1, true)
insert into public.compliance_calendar_items (id, org_id, created_at, updated_at, created_by, due_date, title, description, category, confidence, source_ref, escalate_days, rule_key, active) values
  ('54eecdd7-55ee-456e-84fe-000000000001', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, '2026-11-13', 'DPDP Consent Manager registration', 'Consent Manager registration under the DPDP Rules 2025 (Rule 4) starts. High on date, medium on clause detail; some sources count a day later.', 'dpdp', 'high', 'India solar distributor CRM blueprint.md §3.4, §6 [S44][S45]', '{"14","7","3"}', 'dpdp.consent_manager_registration_date', true),
  ('54eecdd7-55ee-456e-84fe-000000000002', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, '2026-11-30', 'CFA claim deadline — legacy cohort', 'PM Surya Ghar CFA claims for the Phase II legacy cohort must be received by this date (31-Aug-2026 OM). Medium confidence — the OM text was not read (V-1).', 'pmsg', 'medium', 'India solar distributor CRM blueprint.md §3.1, §6 [S3]', '{"14","7","3"}', 'pmsg.claim_deadline.legacy_cohort', true),
  ('54eecdd7-55ee-456e-84fe-000000000003', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, '2026-12-31', 'ALMM List-II exemption ends (commissioning)', 'Net-metering and open-access projects commissioned after this date need List-I modules and List-II cells (18-Jul-2026 OM; no blanket extension). High on date and scope.', 'almm', 'high', 'India solar distributor CRM blueprint.md §3.2, §6 [S15][S16]', '{"14","7","3"}', 'almm.list2.exemption_net_metering_open_access_until', true),
  ('54eecdd7-55ee-456e-84fe-000000000004', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, '2026-12-31', 'BIS self-certification for inverters above 200 kW ends unless extended', 'Self-certification for inverters above 200 kW was extended to this date (S.O. 3706(E)). Report confidence: medium-high.', 'bis', 'medium', 'India solar distributor CRM blueprint.md §3.2, §6 [S23][S74]', '{}', 'bis.inverter_self_cert_until', true),
  ('54eecdd7-55ee-456e-84fe-000000000005', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, '2026-12-31', 'WhatsApp India INR billing migration deadline', 'Meta moves India WhatsApp Business billing to INR; migration must be complete by this date.', 'whatsapp', 'high', 'India solar distributor CRM blueprint.md §3.4, §6 [S53]', '{}', null, true),
  ('54eecdd7-55ee-456e-84fe-000000000006', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, '2027-03-31', 'PMSG programme end and KUSUM Components A and C commissioning', 'PM Surya Ghar programme end per press; PM-KUSUM Components A and C commissioning for sanctions up to 31-Dec-2025. No extension found.', 'pmsg', 'medium', 'India solar distributor CRM blueprint.md §3.1, §6 [S13][S65]', '{}', 'pmsg.programme_end', true),
