  ('54eecdd7-55ee-456e-84fe-000000000008', 'be9c92a8-c19c-4c09-8c39-000000000001', '2026-09-28T06:30:00.000Z', '2026-10-13T06:30:00.000Z', null, '2028-06-01', 'ALMM List-III (ingots and wafers)', 'ALMM extends to ingots and wafers; the first list only follows once at least 3 independent units with 15 GW combined exist. Report confidence: medium-high.', 'almm', 'medium', 'India solar distributor CRM blueprint.md §3.2, §6 [S19]', '{}', 'almm.list3.effective_date', true)
